{"content":"package ledger

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"time"
)

// Rates converts one unit of a currency to USD.
var Rates = map[string]float64{"USD": 1, "EUR": 1.0825, "GBP": 1.2675}

// rateNum holds Rates scaled by 1e4 so conversion can be done in exact
// integer arithmetic: usd = amount * rateNum / 1e4.
var rateNum = map[string]int64{"USD": 10000, "EUR": 10825, "GBP": 12675}

// Event is one log entry.
type Event struct {
	ID       string    `json:"id"`
	Seq      int64     `json:"seq"`
	TS       time.Time `json:"ts"`
	Type     string    `json:"type"`
	Account  string    `json:"account"`
	To       string    `json:"to,omitempty"`
	Amount   int64     `json:"amount"`
	Currency string    `json:"currency"`
	Reverses string    `json:"reverses,omitempty"`
}

// ReadEvents parses a JSONL event log.
func ReadEvents(r io.Reader) ([]Event, error) {
	var out []Event
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64*1024), 1024*1024)
	line := 0
	for sc.Scan() {
		line++
		if len(sc.Bytes()) == 0 {
			continue
		}
		var e Event
		if err := json.Unmarshal(sc.Bytes(), &e); err != nil {
			return nil, fmt.Errorf("line %d: %w", line, err)
		}
		out = append(out, e)
	}
	return out, sc.Err()
}

// toUSD converts an amount in minor units to USD cents, rounded to the
// nearest cent with ties to even (banker's rounding).
func toUSD(amount int64, currency string) (int64, error) {
	num, ok := rateNum[currency]
	if !ok {
		return 0, fmt.Errorf("unknown currency %q", currency)
	}
	x := amount * num
	// Round |x|/1e4 to nearest, ties to even, then restore the sign.
	a := x
	if a < 0 {
		a = -a
	}
	q, r := a/10000, a%10000
	if 2*r > 10000 || (2*r == 10000 && q%2 != 0) {
		q++
	}
	if x < 0 {
		q = -q
	}
	return q, nil
}

// Replay applies the events and returns balances in USD cents.
func Replay(events []Event) (map[string]int64, error) {
	sorted := make([]Event, len(events))
	copy(sorted, events)
	// The log is not sorted: apply events in timestamp order, ties in seq
	// order.
	sort.SliceStable(sorted, func(i, j int) bool {
		if !sorted[i].TS.Equal(sorted[j].TS) {
			return sorted[i].TS.Before(sorted[j].TS)
		}
		return sorted[i].Seq < sorted[j].Seq
	})
	bal := map[string]int64{}
	applied := map[string]Event{}
	reversed := map[string]bool{}
	seen := map[string]bool{}
	for _, e := range sorted {
		// Delivery is at-least-once: only the first occurrence of an id counts.
		if seen[e.ID] {
			continue
		}
		seen[e.ID] = true
		switch e.Type {
		case "deposit", "withdrawal", "transfer":
			usd, err := toUSD(e.Amount, e.Currency)
			if err != nil {
				return nil, fmt.Errorf("event %s: %w", e.ID, err)
			}
			apply(bal, e, usd, 1)
			applied[e.ID] = e
		case "reversal":
			orig, ok := applied[e.Reverses]
			if !ok || reversed[e.Reverses] {
				continue
			}
			usd, err := toUSD(orig.Amount, orig.Currency)
			if err != nil {
				return nil, err
			}
			apply(bal, orig, usd, -1)
			reversed[e.Reverses] = true
		default:
			return nil, fmt.Errorf("event %s: unknown type %q", e.ID, e.Type)
		}
	}
	return bal, nil
}

func apply(bal map[string]int64, e Event, usd int64, sign int64) {
	switch e.Type {
	case "deposit":
		bal[e.Account] += sign * usd
	case "withdrawal":
		bal[e.Account] -= sign * usd
	case "transfer":
		bal[e.Account] -= sign * usd
		bal[e.To] += sign * usd
	}
}
